{
  "contract": "BULLRUNNERSCLUB",
  "closure": {
    "site_function": "withdraw",
    "site_call": ".call",
    "functions": [
      "withdraw",
      "mint"
    ],
    "justification": "Both withdraw and mint functions interact with _ethBal and team_balance, which are exposed during the risky call."
  },
  "protocol": {
    "during_phase": "exposed",
    "allowed_callbacks": [
      "mint"
    ],
    "nesting_bound": {
      "withdraw": 1
    }
  },
  "phases": {
    "function": "withdraw",
    "pre": {
      "name": "pre",
      "from_marker": "start",
      "to_marker": "before_call"
    },
    "exposed": {
      "name": "exposed",
      "from_marker": "before_call",
      "to_marker": "after_call"
    },
    "post": {
      "name": "post",
      "from_marker": "after_call",
      "to_marker": "end"
    },
    "linearization_point": "after_call"
  },
  "ghost_state": [
    {
      "name": "inFlight",
      "sol_type": "uint256",
      "meaning": "Amount of ETH in transit during the callback window",
      "backed_by_storage": false
    }
  ],
  "exposure_invariant": {
    "formula": "team_balance + inFlight <= _ethBal",
    "stable_formula": "team_balance <= _ethBal",
    "kind": "bounded"
  },
  "composition": {
    "target_property": "team_balance <= _ethBal",
    "rule": "The exposure invariant ensures that the team_balance does not exceed _ethBal during the callback, accounting for in-flight ETH."
  }
}
